//! What Kumi can change in Logic Pro (M3 plus the first M4 Loop Range slice): a track's fader, pan and buttons and its name, tracks added and deleted,
//! markers, the tempo, a region's notes as Event List rows, and a plug-in's bypass. Each kind is the bridge's
//! (`daws/logic/logic-kumi/src/changes`), which makes it through one macOS channel and reads it back; what the bridge
//! found no channel for (a marker's name, a plug-in inserted, removed or set, a send, a track
//! moved) isn't declared, and the bridge refuses it saying why. Logic has no undo block, and its own undo keeps a
//! step for a rename, a track or a marker made or deleted and notes written, none for a header's control, the tempo
//! or a bypass: `plan_steps` is false, and Kumi restores values as new writes; added/deleted tracks and deleted markers require manual Logic Undo History; marker additions/moves also do when original identity is incomplete. Those eight kinds, including Loop Range, carry
//! `skipped_by_daw_undo`, as the host's `outside_undo` names them.
use kumi_daw_own::changes::{OwnAction, OwnChangeSet, OwnKind};
use kumi_types::contracts::ChangeFamily::*;
use serde_json::Value;

const MANUAL_UNDO: &str = "Kumi cannot automatically restore this deletion: Logic Pro's Undo title cannot identify Kumi's specific step. Review the appropriate step in Logic Pro's Undo History and undo manually.";

const MANUAL_TRACK_ADD: &str = "Kumi cannot automatically take back this track addition: Logic Pro does not expose all automation, plug-in state or hidden contents. Review the appropriate step in Logic Pro's Undo History and undo manually.";
const MANUAL_LOOP: &str = "Kumi cannot automatically take back this cycle change because its original locator state or meter/timebase identity was not fully confirmed. Restore the cycle locators and on/off state manually in Logic Pro; its own undo does not take this back.";
const MANUAL_MARKER: &str = "Kumi cannot automatically take back this marker change: Logic Pro did not expose every required original field. Showing a field now cannot recover its earlier value. Review the appropriate step in Logic Pro's Undo History and undo manually.";

/// The host validates private original evidence and publishes only this restore capability.
/// Missing, legacy and malformed hints never imply known original contents.
fn marker_manual_undo(applied: &Value) -> Option<&'static str> {
    conditional_manual_undo(applied, MANUAL_MARKER)
}
fn loop_manual_undo(applied: &Value) -> Option<&'static str> {
    conditional_manual_undo(applied, MANUAL_LOOP)
}
fn conditional_manual_undo(applied: &Value, note: &'static str) -> Option<&'static str> {
    let hint = applied.pointer("/undo/restore");
    let value = hint.and_then(Value::as_object).is_some_and(|hint| hint.len() == 1 && hint.get("mode").is_some_and(|mode| mode == "value"));
    (!value).then_some(note)
}

const PLAN: &str = "Make changes in Logic Pro in one call, in order: each step is one of your change tools or a step below with its input, and \"@name\" in an input stands for what an earlier step marked as: \"name\" made (a new track, a new marker). A wait step ({\"beats\": 8} or {\"seconds\": 4}) pauses between steps. Logic Pro has no undo block: a step that renames, adds or deletes a track, makes, moves or deletes a marker, or writes notes is one step of Logic Pro's own undo (Cmd-Z in Logic Pro takes back the last one only), and a fader, pan, mute, solo, arm, tempo, bypass or cycle step is none, since Logic Pro's undo doesn't keep those. It stops at the first step that fails and says what was done. With final: true and every step done, Kumi tells the producer what changed and the answer ends there, with no reply from you: use it when the changes complete the request, even a single change.";
const UNDO: &str = "Undo one of your changes from this session: pass its change id (such as c3), or \"last\" for the latest one. Kumi puts back exactly what that change set, as a new write in Logic Pro; it only works while nobody changed the same thing in Logic Pro since, and if so, say what happened (discard: true puts it back anyway, only when the producer asks). Kumi cannot automatically take back added tracks, deleted tracks or deleted markers. Marker additions and moves also need manual undo if any original identity field was unavailable; showing the field later cannot recover the earlier value. For deletions, Logic Pro's Undo title cannot prove which step is Kumi's. Tell the producer to review the appropriate step in Logic Pro's Undo History and undo manually. Discard never overrides missing identity or a manual-only change. With final: true, when the undo is all that was asked, Kumi tells the producer and the answer ends there, with no reply from you.";
const INSTRUCTIONS: &str = "Change Logic Pro with your change tools, or several changes at once with make_changes, using the refs your reads gave. Logic Pro's own undo keeps a step for a rename, a track or a marker made or deleted and notes written, and none for a fader, pan, mute, solo, arm, tempo or bypass; the cycle also makes no native undo step (its Edit menu stays as it was); undo_change restores value changes as new writes; added tracks, deleted tracks and deleted markers require the producer to use Logic Pro's Undo History manually. Marker additions and moves also require manual undo when the captured original identity is incomplete (including an unexposed Text column); showing a field later cannot recover its old contents. Loop Range is the first M4 slice only: startBeats/endBeats set the cycle and 0/0 disables it without erasing locators. Unknown or changed original meter/timebase and producer cycle edits refuse restore, including discard. Other M4 changes remain unavailable. Kumi does not press an Undo step identified only by its title. Kumi changes Logic Pro through its own window and reads each value back: a change Logic Pro didn't show is answered as uncertain, so read it before going on. Adding or deleting a track makes Logic Pro's refs new: read again before using older ones (a ref the change made comes back with it). Positions are positionBeats, beats (quarter notes) from the project's start; Logic Pro shows them as bars. Pan runs -1 (left) to 1 (right) here, though Logic Pro's strips show -64 to 63; the tempo takes whole BPM; Logic Pro names markers itself. The observation's kumiChanges lists your latest changes and where each stands (applied, undone, kept, unsure, or expired: Kumi can't undo it any more, and its note says who can); value-backed property and rename reversions can be recognized after the producer uses Logic undo. Marker, note and structural steps have no title-only undo attribution; verify them by reading Logic, not by memory.";

pub static CHANGES: OwnChangeSet = OwnChangeSet {
    kinds: &KINDS,
    actions: &ACTIONS,
    plan_description: PLAN,
    undo_description: UNDO,
    instructions: INSTRUCTIONS,
    plan_steps: false,
    most_track_adds: None,
};

static ACTIONS: [OwnAction; 3] = [
    OwnAction { tool: "play", method: "transport_play", description: "Start Logic Pro playing from the playhead.", schema: r#"{"type":"object","additionalProperties":false,"properties":{}}"#, core: true, playing: Some(true), title: "Playing" },
    OwnAction { tool: "stop", method: "transport_stop", description: "Stop Logic Pro's playback and recording.", schema: r#"{"type":"object","additionalProperties":false,"properties":{}}"#, core: true, playing: Some(false), title: "Stopped" },
    OwnAction { tool: "set_cursor", method: "cursor_set", description: "Move Logic Pro's playhead to positionBeats (beats from the project's start, to the bar and beat) or position (seconds at the project's tempo); playback follows while it plays.", schema: r#"{"type":"object","additionalProperties":false,"properties":{"positionBeats":{"type":"number","minimum":0},"position":{"type":"number","minimum":0}}}"#, core: false, playing: None, title: "Moved the playhead" },
];

